   "codice": "extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var main := await instantiate_main_scene()
	if not check("main", main != null, "La scena principale deve aprirsi senza errori"):
		return
	var walls := find_by_name(main, "Walls") as TileMapLayer
	if not check("walls", walls != null, "Nella scena serve il nodo Walls"):
		return
	var cell_tile: Vector2i = walls.get_cell_atlas_coords(Vector2i(10, 10))
	check("cell_painted", cell_tile == Vector2i(3, 0), "La cella (10, 10) di Walls deve contenere la tessera (3, 0) (trovata %s)" % str(cell_tile))
	var player := find_by_name(main, "Player") as CharacterBody2D
	if not check("player", player != null, "Nella scena deve esserci il Player"):
		return
	player.position = Vector2(168, 220)
	await hold_action("move_up", 30)
	check("wall_solid", player.position.y > 175.0, "Il personaggio deve fermarsi contro il muro a tessere e non attraversarlo (Y = %.1f)" % player.position.y)
